// Phase 1 / Module 9: Exception Handling and File Management.
"use strict";
const { chain, graph, table } = require("./render");
const { mcq, task } = require("./lib");

const lessons = [];

// ---------------------------------------------------------------- 1
lessons.push({
  title: "Kinds of Errors and How to Read a Traceback",
  minutes: 35,
  learn: ["Separate syntax errors, runtime errors (exceptions) and logic errors", "Name the common built-in exceptions and what causes them", "Read a traceback from the bottom up", "Debug a logic error with prints and small tests"],
  why: "Programs fail for many reasons: typing mistakes, bad input, missing files, wrong formulas. Knowing which kind of failure you have tells you where to look.",
  realWorld: "A payment service logs the traceback of a failed request; the developer reads the last line and the file name to find the cause within minutes.",
  simple: "A <strong>syntax error</strong> stops the program before it starts. A <strong>runtime error</strong> (an <em>exception</em>) stops it while running. A <strong>logic error</strong> lets it finish but gives a wrong answer.",
  detail: `${table(["Exception", "Typical cause", "Example"], [["SyntaxError / IndentationError", "invalid code structure", "missing colon, bad indentation"], ["NameError", "name not defined", "using a variable before assigning it, typo"], ["TypeError", "wrong type for an operation", "<code>\"5\" + 3</code>, calling an int"], ["ValueError", "right type, unsuitable value", "<code>int(\"abc\")</code>"], ["ZeroDivisionError", "division or modulo by zero", "<code>5 / 0</code>"], ["IndexError", "list index out of range", "<code>[1, 2][5]</code>"], ["KeyError", "dictionary key missing", "<code>{}[\"a\"]</code>"], ["AttributeError", "object has no such attribute", "<code>\"a\".push(1)</code>"], ["FileNotFoundError", "file or folder does not exist", "<code>open(\"missing.txt\")</code>"], ["ModuleNotFoundError", "module cannot be imported", "<code>import not_installed</code>"], ["RecursionError", "too many nested calls", "recursion without a base case"]])}
<h3>Reading a traceback</h3>
<p>The traceback lists the calls that led to the error, oldest first. The <strong>last line</strong> names the exception and its message. The line above it shows the exact code and file line. Start there, then read upward to see who called it.</p>
<h3>Logic errors</h3>
<p>No message appears, so you must find them yourself: re-read the requirement, test small inputs with known answers, print intermediate values, and check the boundaries (empty, one item, the limits).</p>
<h3>Exceptions are objects</h3>
<p>Every exception is a class in a hierarchy (next lesson). That is why <code>except ArithmeticError</code> also catches <code>ZeroDivisionError</code>.</p>`,
  syntax: { code: `Traceback (most recent call last):\n  File "app.py", line 7, in <module>\n    print(10 / 0)\nZeroDivisionError: division by zero`, lang: "text", note: "The last line is the most important." },
  diagram: chain("Three kinds of errors", "Left to right: syntax error found before running, runtime error found while running, logic error found only by checking the result.",
    [{ k: "proc", t: "Syntax error\nbefore running" }, { k: "proc", t: "Runtime error\nwhile running" }, { k: "proc", t: "Logic error\nwrong answer" }], { w: 170, gap: 40, hgt: 60 }),
  example: { code: `def attempt(label, action):\n    try:\n        action()\n    except Exception as error:\n        print(label, "->", type(error).__name__ + ":", error)\n\nattempt("zero", lambda: 10 / 0)\nattempt("index", lambda: [1, 2][5])\nattempt("key", lambda: {"a": 1}["b"])\nattempt("value", lambda: int("abc"))\nattempt("type", lambda: "5" + 3)\nattempt("name", lambda: undefined_name)\nattempt("attribute", lambda: "text".push(1))`, out: `zero -> ZeroDivisionError: division by zero\nindex -> IndexError: list index out of range\nkey -> KeyError: 'b'\nvalue -> ValueError: invalid literal for int() with base 10: 'abc'\ntype -> TypeError: can only concatenate str (not "int") to str\nname -> NameError: name 'undefined_name' is not defined\nattribute -> AttributeError: 'str' object has no attribute 'push'` },
  lineByLine: [["def attempt(label, action):", "A helper that runs a function and reports any exception (the try/except is explained in the next lesson)."], ["lambda: 10 / 0", "A tiny function that fails when called."], ["type(error).__name__", "The exception's class name."], ["error", "Printing an exception shows its message."]],
  dryRun: { intro: "Reading <code>ValueError: invalid literal for int() with base 10: 'abc'</code>:", headers: ["Part", "Meaning"], rows: [["ValueError", "kind of problem: the value is unsuitable"], ["invalid literal for int()", "what failed: converting text to an int"], ["with base 10: 'abc'", "the offending text"]] },
  realExample: { intro: "A logic error: the formula runs without complaint but is wrong. Compare the two lines.", code: `marks = [60, 80, 100]\nwrong = sum(marks) / len(marks) + 1\nright = sum(marks) / len(marks)\nprint(wrong, right)`, out: `81.0 80.0` },
  mistakes: ["Fixing the line number only: the cause may be earlier.", "Ignoring the message text.", "Guessing instead of printing values.", "Catching every error silently so nothing is visible.", "Confusing SyntaxError (cannot start) with a runtime error."],
  practices: ["Read the last line first.", "Reproduce the bug with the smallest input.", "Change one thing at a time.", "Search the exact message in the official docs."],
  interview: ["Types of errors in Python?", "Difference between a syntax error and an exception?", "How do you debug a logic error?", "What does the last line of a traceback tell you?"],
  practiceQs: ["Which exception does int(\"3.5\") raise?", "Which exception does [].pop() raise?", "Why is a wrong formula not reported by Python?", "What does KeyError: 'name' mean?"],
  revision: ["Syntax: before running. Runtime: exception. Logic: wrong result.", "Traceback: last line = what, line above = where.", "Common exceptions and their causes."],
  hinglish: "Syntax error program chalne se pehle aati hai, runtime error chalte waqt (exception) aur logic error mein program chalta hai par jawab galat hota hai. Traceback hamesha neeche se padhna shuru karo.",
  quiz: [
    mcq("Which exception does int(\"abc\") raise?", ["TypeError", "ValueError", "NameError", "KeyError"], 1, "The type is right (a string) but the value cannot be converted.", "OUTPUT_PREDICTION"),
    mcq("Which exception does [1, 2, 3][10] raise?", ["KeyError", "ValueError", "IndexError", "NameError"], 2, "The index is out of range.", "OUTPUT_PREDICTION"),
    mcq("A program runs but prints the wrong total. This is a:", ["Syntax error", "Logic error", "NameError", "ImportError"], 1, "No exception: the formula is wrong."),
    mcq("Where is the most useful line of a traceback?", ["The first line", "The last line", "The middle", "None"], 1, "It names the exception and message."),
    mcq("Which exception means a dictionary key is missing?", ["IndexError", "KeyError", "AttributeError", "ValueError"], 1, "Dictionaries raise KeyError."),
  ],
  tasks: [task("Debug the average", "The program should print the average of the marks, rounded to 2 decimals, but it divides by the wrong number. Fix it. Input: one line of integers.", "marks = list(map(int, input().split()))\nprint(round(sum(marks) / (len(marks) + 1), 2))\n", `marks = list(map(int, input().split()))\nprint(round(sum(marks) / len(marks), 2))`, [["60 80 100", "80.0"], ["1 2", "1.5"]], [["60 80 100", "80.0"], ["1 2", "1.5"], ["5", "5.0"], ["10 20 25", "18.33"]])],
});

